/**
 * チリのクイズ。
 *
 * 都市カードに書いた具体的事実(アントファガスタの関税紛争・ウンベルストネの
 * フィチャ通貨・サンティアゴのスモッグ・バルパライソのパナマ運河・
 * プエルト・モントのドイツ移民など)はここでは繰り返して問わない。
 *
 * 南アメリカ大陸盤・ペルー盤・ボリビア盤・世界一周盤の既存クイズ
 * (2026-08-21時点)と重ならないよう、以下は避けている。
 *   - ハーバー・ボッシュ法による硝石産業の崩壊(南アメリカ大陸盤に既出)
 *   - チンチョーロ族のミイラ(南アメリカ大陸盤)
 *   - アタカマ砂漠の天文台が置かれる理由(南アメリカ大陸盤)
 *   - 「世界一乾燥した砂漠」(世界一周盤)
 *   - 「世界最大の銅輸出国」(南アメリカ大陸盤)
 *   - 太平洋岸に沿う細長い国という一般的な問い(南アメリカ大陸盤)
 *   - 太平洋戦争の同盟関係を一般的に問う設問(ペルー盤)
 *   - 太平洋岸を失った戦争(ボリビア盤)
 *   - サン・マルティンのアンデス越え(南アメリカ大陸盤)
 */
function t(source) {
  const parts = source.split("|");
  if (parts.length !== 4) {
    throw new Error(`4言語(en|es|fr|ja)で書いてください: ${source.slice(0, 60)}…`);
  }
  const [en, es, fr, ja] = parts;
  return { en, es, fr, ja };
}

function q(difficulty, question, options, a, fact) {
  return { difficulty, q: t(question), o: options.map(t), a, f: t(fact) };
}

